import{c as t,Q as o,j as a,m as i}from"./chunks/framework.BXc4yaFE.js";const c=JSON.parse('{"title":"Loop engineering: the 14-step roadmap from prompter to loop designer.","description":"","frontmatter":{},"headers":[],"relativePath":"research/tweets/2026-06-09-@0xCodez-773029.md","filePath":"research/tweets/2026-06-09-@0xCodez-773029.md","lastUpdated":1785909234000}'),n={name:"research/tweets/2026-06-09-@0xCodez-773029.md"};function s(r,e,l,h,p,d){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="loop-engineering-the-14-step-roadmap-from-prompter-to-loop-designer" tabindex="-1">Loop engineering: the 14-step roadmap from prompter to loop designer. <a class="header-anchor" href="#loop-engineering-the-14-step-roadmap-from-prompter-to-loop-designer" aria-label="Permalink to &quot;Loop engineering: the 14-step roadmap from prompter to loop designer.&quot;">​</a></h1><p><strong>作者</strong>：Codez (@0xCodez)<br><strong>發布時間</strong>：2026-06-09<br><strong>原始連結</strong>：<a href="https://x.com/0xcodez/status/2064374643729773029" target="_blank" rel="noreferrer">https://x.com/0xcodez/status/2064374643729773029</a><br><strong>類型</strong>：Twitter Article<br><strong>統計</strong>：❤️ 605 · 🔁 104 · 🔖 1,355 · 👁 121,393</p><hr><h2 id="分析摘要" tabindex="-1">分析摘要 <a class="header-anchor" href="#分析摘要" aria-label="Permalink to &quot;分析摘要&quot;">​</a></h2><p><strong>TL;DR</strong>：14 步驟三層次路線圖（Why/Building Blocks/Build It），含 4 條件前置測試、MVP Loop 公式、Ralph Wiggum Loop 失敗模式、comprehension debt + security tax——是本批最具防坑實用性的文章。</p><h3 id="核心論點" tabindex="-1">核心論點 <a class="header-anchor" href="#核心論點" aria-label="Permalink to &quot;核心論點&quot;">​</a></h3><ol><li><strong>Loop 的 4 條件前置測試</strong>（最獨特貢獻）：必須同時滿足：(1) 任務重複發生 (2) 驗證可自動化 (3) Token 預算可承擔廢棄消耗 (4) Agent 有資深工程師工具（logs/reproduction env/執行能力）——缺一不可，否則 loop 比 prompt 貴</li><li><strong>最小可行 loop（MVP）公式</strong>：One automation + One skill + One state file + One gate；順序固定（先手動穩定 → skill → loop → schedule，跳步就失敗）</li><li><strong>Ralph Wiggum Loop</strong>（Geoffrey Huntley 命名）：agent 未完成時提前 emit 完成 token，loop 靜默退出；根本原因是缺乏硬性 objective gate</li><li><strong>三大風險漸增</strong>：comprehension debt（code 比你快）/ cognitive surrender（停止形成意見）/ security tax（unattended loop = unattended attack surface）</li><li><strong>安全威脅模型</strong>：PR 未審 merge / Skills 注入向量（17,022 skills 中 520 個洩露憑證）/ logs 散佈 secrets / 權限蔓延（30 天審計一次）</li></ol><h3 id="關鍵技術細節" tabindex="-1">關鍵技術細節 <a class="header-anchor" href="#關鍵技術細節" aria-label="Permalink to &quot;關鍵技術細節&quot;">​</a></h3><ul><li><strong>正確衡量指標</strong>：<code>cost per accepted change</code>（非 tokens spent）；接受率 &lt; 50% = loop 虧損</li><li>STATE.md 兩種架構：Markdown in repo（版本控制、diff 可讀）vs 外部系統（Linear/GitHub Issues，跨 repo 可見）</li><li>Anthropic 2026 數據：工程師每日 merge 8×（Anthropic 自稱「幾乎肯定高估實際生產力增益」）</li><li>Goal drift 緩解：每 run 重讀 VISION.md / AGENTS.md（不只 SKILL.md）</li><li>Self-preferential bias 緩解：verifier subagent 不接觸 maker 的推理過程</li></ul><h3 id="批判性觀察" tabindex="-1">批判性觀察 <a class="header-anchor" href="#批判性觀察" aria-label="Permalink to &quot;批判性觀察&quot;">​</a></h3><ol><li><strong>4 條件測試是本批最誠實的防坑工具</strong>——明確說「大多數開發者還不需要 loop」；相比 addyosmani/sairahul1 版本更平衡</li><li><strong>Ralph Wiggum Loop + 520/17,022 統計</strong>是此批文章唯一有具體研究來源的安全量化數據（若可驗證）</li><li>大量引用 Addy Osmani，原創框架佔比有限；但整合與操作化做得最好</li></ol><hr><h2 id="評分" tabindex="-1">評分 <a class="header-anchor" href="#評分" aria-label="Permalink to &quot;評分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>維度</th><th>分數</th><th>理由</th></tr></thead><tbody><tr><td>A. Workspace 可行動性</td><td>9/10</td><td>4 條件測試可立即套用新 loop 設計前；MVP 公式直接可執行；<code>cost per accepted change</code> 指標可用</td></tr><tr><td>B. 創新性</td><td>8/10</td><td>Ralph Wiggum Loop + 4 條件 gate；security tax（skills 注入統計）是新材料</td></tr><tr><td>C. 證據品質</td><td>7/10</td><td>AlphaSignal 分析、Geoffrey Huntley 研究、Anthropic 8x 數據（含自我否定）；520/17,022 skills 統計</td></tr><tr><td>D. 技術深度</td><td>8/10</td><td>STATE.md 兩種架構；三種失敗模式有具體緩解方案；安全威脅模型完整</td></tr><tr><td>E. 泛化性</td><td>9/10</td><td>14 步驟跨工具/跨域；安全稅適用所有 unattended automation</td></tr><tr><td><strong>加權總分</strong></td><td><strong>8.25/10</strong></td><td>A×0.3 + B×0.2 + C×0.2 + D×0.15 + E×0.15</td></tr></tbody></table><p><strong>整合決策</strong>：Rule（多處）<br><strong>整合位置</strong>：</p><ul><li><code>core.md</code>：加入 4 條件 loop gate</li><li><code>subagent-strategy.md</code>：Ralph Wiggum Loop 防範（objective gate 要求）</li><li><code>security-hygiene.md</code>：skills 注入向量警示<br><strong>整合狀態</strong>：待實作</li></ul><hr><h2 id="全文" tabindex="-1">全文 <a class="header-anchor" href="#全文" aria-label="Permalink to &quot;全文&quot;">​</a></h2><p>Most developers still prompt their coding agents by hand. They type, they wait, they read the diff, they type again. 9 out of 10 builders have never written a single loop that prompts the agent for them.</p><p>No automation, no state file, no verifier, no schedule. The leverage point has moved - from typing prompts to designing systems that prompt. This is the 14-step roadmap from prompter to loop designer.</p><p>This is the 14-step roadmap to make that shift - sourced from Anthropic&#39;s engineering docs, Addy Osmani&#39;s long-form on loop engineering, and recent measurement studies.</p><p>Three tiers: figure out if you actually need a loop, learn the five building blocks, then build the smallest one that works without hurting you.</p><p>14 steps. 3 tiers. Stop prompting. Start designing.</p><hr><p>PART 1 · The Why &amp; The Test</p><h2 id="_01-loop-engineering-is-replacing-yourself-as-the-prompter" tabindex="-1">01. Loop engineering is replacing yourself as the prompter. <a class="header-anchor" href="#_01-loop-engineering-is-replacing-yourself-as-the-prompter" aria-label="Permalink to &quot;01. Loop engineering is replacing yourself as the prompter.&quot;">​</a></h2><p>For two years, the way you got something out of a coding agent was: write a prompt, share the context, read what came back, write the next prompt. The agent was a tool and you held it the entire time. That part is ending.</p><p>Loop engineering is building a small system that finds the work, hands it to the agent, checks the result, records what happened, and decides the next move - on its own. You design that system once. The system prompts the agent from then on.</p><p>Anthropic engineers now merge eight times as much code per day as they did in 2024 - a figure Anthropic itself calls &quot;almost certainly an overstatement of the true productivity gain.&quot;</p><p>The number is debated. The mechanism isn&#39;t: the leverage point moved from typing prompts to designing the loop that prompts.</p><h2 id="_02-run-the-4-condition-test-before-you-build-anything" tabindex="-1">02. Run the 4-condition test before you build anything. <a class="header-anchor" href="#_02-run-the-4-condition-test-before-you-build-anything" aria-label="Permalink to &quot;02. Run the 4-condition test before you build anything.&quot;">​</a></h2><p>Loops earn their cost under four conditions. Miss one and the loop costs more than it returns. The honest take from AlphaSignal&#39;s analysis:</p><p>The four conditions in plain English:</p><ul><li><p><strong>The task repeats.</strong> A loop amortizes its setup across many runs. For a one-time job, a good prompt is faster and cheaper. If the work does not recur weekly, you don&#39;t have a loop - you have a script you ran once.</p></li><li><p><strong>Verification is automated.</strong> The loop needs something that can fail the work without you in the room. A test suite, a type checker, a linter, a build. No automated check means you&#39;re back in the chair reading every diff - the exact job the loop was supposed to remove.</p></li><li><p><strong>Your token budget can absorb the waste.</strong> Loops re-read context, retry, explore. That burns tokens whether or not the run ships anything. The technique scales with budget, which is why it reads as obvious to people with effectively free tokens and reckless to people on a metered plan.</p></li><li><p><strong>The agent has a senior engineer&#39;s tools.</strong> Logs, a reproduction environment, the ability to run the code it writes and see what breaks. Without that, the loop iterates blind.</p></li></ul><h2 id="_03-the-shape-of-a-loop" tabindex="-1">03. The shape of a loop. <a class="header-anchor" href="#_03-the-shape-of-a-loop" aria-label="Permalink to &quot;03. The shape of a loop.&quot;">​</a></h2><p>A loop is not a single agent call.</p><p>DISCOVER → PLAN → EXECUTE → VERIFY → (loop back if failed)</p><p>The output is not a response. It is a state change that satisfies the stop condition or hands back a diagnosis.</p><h2 id="_04-two-kinds-of-loops" tabindex="-1">04. Two kinds of loops. <a class="header-anchor" href="#_04-two-kinds-of-loops" aria-label="Permalink to &quot;04. Two kinds of loops.&quot;">​</a></h2><p><strong>Open Loop</strong>: The agent explores freely. No hard stop condition. Powerful. Expensive. Needs near-unlimited token budget. Best for research and discovery.</p><p><strong>Closed Loop</strong>: The agent runs until a verifiable condition is true. Tests pass. Lint is clean. Schema matches. Binary checks, not feelings. This is the one that actually works for most people today.</p><hr><p>PART 2 · The Five Building Blocks</p><h2 id="_05-automations-—-the-heartbeat" tabindex="-1">05. Automations — the heartbeat. <a class="header-anchor" href="#_05-automations-—-the-heartbeat" aria-label="Permalink to &quot;05. Automations — the heartbeat.&quot;">​</a></h2><p>Automations are what make a loop an actual loop and not just one run you did once.</p><p><strong>Claude Code</strong>: <code>/loop</code>, <code>/schedule</code>, hooks at lifecycle points, GitHub Actions for runs that outlive the laptop.</p><p><strong>Codex</strong>: Automations tab — pick project, prompt, cadence, local checkout or background worktree.</p><p><strong>The <code>/goal</code> primitive</strong>: keeps going until a condition you wrote is actually true. After every turn, a separate small model checks whether you&#39;re done. The agent that wrote the code is not the one grading it.</p><h2 id="_06-worktrees-—-parallel-without-chaos" tabindex="-1">06. Worktrees — parallel without chaos. <a class="header-anchor" href="#_06-worktrees-—-parallel-without-chaos" aria-label="Permalink to &quot;06. Worktrees — parallel without chaos.&quot;">​</a></h2><p>Two agents writing the same file is the same headache as two engineers committing to the same lines without talking. A git worktree is a separate working directory on its own branch, sharing the same repo history. One agent&#39;s edits cannot touch the other&#39;s checkout.</p><p><strong>Claude Code</strong>: <code>--worktree</code> flag, <code>isolation: worktree</code> on subagents (each helper gets a fresh checkout that cleans itself up after).</p><p><strong>Codex</strong>: worktree support built in.</p><p>Your review bandwidth is still the ceiling. Worktrees remove the collision. You remove the bottleneck.</p><h2 id="_07-skills-—-so-you-stop-explaining-your-project-every-single-time" tabindex="-1">07. Skills — so you stop explaining your project every single time. <a class="header-anchor" href="#_07-skills-—-so-you-stop-explaining-your-project-every-single-time" aria-label="Permalink to &quot;07. Skills — so you stop explaining your project every single time.&quot;">​</a></h2><p>A skill is how you stop re-explaining the same project context every session.</p><p>Both tools use the same format: a folder with a SKILL.md inside, plus optional scripts, references, assets.</p><p>Without skills: the loop re-derives your whole project from zero every cycle. With skills: it compounds.</p><p>→ VISION.md — what success looks like → ARCHITECTURE.md — the tech stack and folder structure → RULES.md — what the agent is never allowed to do</p><h2 id="_08-plugins-and-connectors-—-the-loop-touches-your-real-tools" tabindex="-1">08. Plugins and connectors — the loop touches your real tools. <a class="header-anchor" href="#_08-plugins-and-connectors-—-the-loop-touches-your-real-tools" aria-label="Permalink to &quot;08. Plugins and connectors — the loop touches your real tools.&quot;">​</a></h2><p>A loop that can only see the filesystem is a tiny loop.</p><p>Connectors (MCP) let the agent read your issue tracker, query a database, hit a staging API, drop a message in Slack. Codex and Claude Code both speak MCP so the connector you wrote for one usually works in the other.</p><p>This is the difference between an agent that says &quot;here is the fix&quot; and a loop that opens the PR, links the Linear ticket, and pings the channel once CI is green - by itself.</p><h2 id="_09-subagents-—-keep-the-maker-away-from-the-checker" tabindex="-1">09. Subagents — keep the maker away from the checker. <a class="header-anchor" href="#_09-subagents-—-keep-the-maker-away-from-the-checker" aria-label="Permalink to &quot;09. Subagents — keep the maker away from the checker.&quot;">​</a></h2><p>The model that wrote the code is too nice grading its own homework.</p><p>The usual split: one agent explores, one implements, one verifies against the spec.</p><p>This is also what <code>/goal</code> does under the hood. A fresh model decides if the loop is done - not the one that did the work.</p><p>Subagents burn more tokens. Spend them where a second opinion is worth paying for.</p><hr><p>PART 3 · Build It Right</p><h2 id="_10-the-state-file-—-the-spine-of-the-whole-loop" tabindex="-1">10. The state file — the spine of the whole loop. <a class="header-anchor" href="#_10-the-state-file-—-the-spine-of-the-whole-loop" aria-label="Permalink to &quot;10. The state file — the spine of the whole loop.&quot;">​</a></h2><p>The model forgets everything between runs. The repo does not.</p><p>A markdown file, a Linear board, anything that lives outside the single conversation and holds what&#39;s done and what is next.</p><p>Two patterns for where the state file lives:</p><ul><li><p><strong>Markdown in the repo</strong> - STATE.md at the root or inside .claude/. Version-controlled. Simple. Diff-readable. Best for solo or small team work.</p></li><li><p><strong>External system (Linear, GitHub Issues, a database)</strong> - survives across repos, queryable, supports team-wide visibility. Best for production loops where multiple humans need to see what the loop is doing.</p></li></ul><p>For long-running loops that risk drifting off the goal, pair the state file with a standing high-level spec - VISION.md or AGENTS.md - that the agent rereads each run. State tells the agent where it is. The spec tells it where to go.</p><h2 id="_11-the-minimum-viable-loop" tabindex="-1">11. The minimum viable loop. <a class="header-anchor" href="#_11-the-minimum-viable-loop" aria-label="Permalink to &quot;11. The minimum viable loop.&quot;">​</a></h2><p>If you passed the 4-condition test in step 2, build the smallest loop that works before anything fancy. Four parts, no swarm.</p><ul><li><p><strong>One automation.</strong> A scheduled run that fires on a cadence and stops on a clear condition. Use <code>/loop</code> in Claude Code or an automation in Codex. Pair with <code>/goal</code> when you want it to run until a stated condition holds.</p></li><li><p><strong>One skill.</strong> A single SKILL.md that stores the project context the agent would otherwise re-derive from zero every run.</p></li><li><p><strong>One state file.</strong> A markdown file or a Linear board that records what is done and what is next. Tomorrow&#39;s run resumes instead of restarting.</p></li><li><p><strong>One gate.</strong> The test, type check, or build that fails bad work automatically. This is the part that decides whether the loop helps or just spends.</p></li></ul><p><strong>Order matters</strong>: get one manual run reliable first → turn it into a skill → wrap it in a loop → then schedule it. Skipping ahead is how loops fail in production.</p><p><strong>The metric that matters</strong>: cost per accepted change - not tokens spent, not tasks attempted, not loops scheduled. If your accepted-change rate is below 50% you&#39;re doing review work the loop saved you from, and the loop is losing.</p><h2 id="_12-the-ralph-wiggum-loop-loops-that-fail-quietly" tabindex="-1">12. The Ralph Wiggum loop. Loops that fail quietly. <a class="header-anchor" href="#_12-the-ralph-wiggum-loop-loops-that-fail-quietly" aria-label="Permalink to &quot;12. The Ralph Wiggum loop. Loops that fail quietly.&quot;">​</a></h2><p>Engineer Geoffrey Huntley documented this failure mode and named it. An agent meant to emit a completion token only when finished emits it early, and the loop exits on a half-done job. Without a hard gate, loops fail quietly and keep spending.</p><p><strong>The Ralph Wiggum loop is what happens when:</strong></p><ul><li><p>No real verifier. Just a second agent asked to &quot;review,&quot; no objective signal. Two optimists agreeing.</p></li><li><p>Soft completion conditions. &quot;Done&quot; defined by the agent&#39;s judgment, not by a test, build, or type check.</p></li><li><p>No hard stops. Loop continues until something external kills it (rate limit, you noticing) rather than until success is verified.</p></li></ul><p><strong>The fix</strong>: something objective that can fail the work. A test that passes or fails. A build that compiles or doesn&#39;t. A linter that returns zero or non-zero. Not a verifier that has an opinion.</p><p><strong>Other measured failure modes:</strong></p><ul><li><p>Goal drift over long sessions. Each summarization step is lossy; &quot;don&#39;t do X&quot; constraints disappear at turn 47. Mitigation: a standing VISION.md or AGENTS.md reread each run.</p></li><li><p>Self-preferential bias. The agent that wrote the code is too nice grading its own homework. Mitigation: a separate verifier subagent with no exposure to the maker&#39;s reasoning.</p></li><li><p>Agentic laziness. The loop declares &quot;done enough&quot; at partial completion. Mitigation: <code>/goal</code> with an objective stop condition checked by a fresh model.</p></li></ul><h2 id="_13-comprehension-debt-and-cognitive-surrender" tabindex="-1">13. Comprehension debt and cognitive surrender. <a class="header-anchor" href="#_13-comprehension-debt-and-cognitive-surrender" aria-label="Permalink to &quot;13. Comprehension debt and cognitive surrender.&quot;">​</a></h2><p><strong>Comprehension debt.</strong> The faster the loop ships code you didn&#39;t write, the larger the distance between what the repository contains and what you understand. The bill that hurts is not the token bill. It is the day you have to debug a system no one on the team has read.</p><p><strong>Cognitive surrender.</strong> The pull to stop forming an opinion and accept whatever the loop returns. Designing the loop is the cure when you do it with judgment and the accelerant when you do it to avoid thinking. Same action, opposite result.</p><p>The mitigations are not technical:</p><ul><li><p>Read the diffs. If you don&#39;t read what the loop ships, you&#39;re renting comprehension debt at compound interest.</p></li><li><p>Spot-check the gate. Pick a few PRs the loop opened and verify the test that approved them actually catches the failure mode you care about. Gates rot.</p></li><li><p>Block the loop from architecture work. Keep it on small, machine-checkable changes. The moment you let it touch judgment calls, comprehension debt accelerates.</p></li><li><p>Pair-design loops with a teammate. A second pair of eyes when designing the loop catches blind spots the loop will exploit forever otherwise.</p></li></ul><h2 id="_14-the-security-tax-an-unattended-loop-is-an-unattended-attack-surface" tabindex="-1">14. The security tax. An unattended loop is an unattended attack surface. <a class="header-anchor" href="#_14-the-security-tax-an-unattended-loop-is-an-unattended-attack-surface" aria-label="Permalink to &quot;14. The security tax. An unattended loop is an unattended attack surface.&quot;">​</a></h2><p>The threat model your loop has to defend against:</p><ul><li><p><strong>Generated code shipping unreviewed.</strong> Without a gate that includes security checks (SAST, dependency audit, secret scanning), insecure code merges automatically.</p></li><li><p><strong>Skills as injection vectors.</strong> A loop that auto-installs skills inherits every prompt injection hiding in their descriptions. Audit skill sources before installing. (520 of 17,022 audited skills leak credentials.)</p></li><li><p><strong>Credentials in logs.</strong> Debug logging during a long-running loop scatters secrets across logs you don&#39;t monitor. Disable verbose logging in production loops; sanitize what does get logged.</p></li><li><p><strong>Permission scope creep.</strong> A loop tested with read-only permissions gets &quot;just one&quot; write permission added for convenience, then never re-audited. Re-audit permissions every 30 days.</p></li></ul><hr><h2 id="the-mistakes-that-turn-loops-into-money-pits" tabindex="-1">The mistakes that turn loops into money pits <a class="header-anchor" href="#the-mistakes-that-turn-loops-into-money-pits" aria-label="Permalink to &quot;The mistakes that turn loops into money pits&quot;">​</a></h2><ul><li>Building a loop without running the 4-condition test.</li><li>No objective gate. A second agent asked to &quot;review&quot; without a test is just a second optimist.</li><li>One agent doing both writing and verifying. Self-preferential bias.</li><li>No state file. Tomorrow&#39;s run restarts from zero instead of resuming.</li><li>Vague stop conditions. &quot;Done when it looks good&quot; never holds.</li><li>No token budget cap. Ambitious loops burn 5–10× the tokens you expected.</li><li>Auto-installing community skills. 520 of 17,022 audited skills leak credentials. Read the source before installing.</li><li>Loops on judgment-call work. Architecture, auth, payments, vague product decisions. Keep the loop on lint-and-fix.</li><li>Not reading the diffs. Comprehension debt at compound interest.</li></ul><hr><h2 id="conclusion-the-leverage-moved-your-job-did-too" tabindex="-1">Conclusion: The leverage moved. Your job did too. <a class="header-anchor" href="#conclusion-the-leverage-moved-your-job-did-too" aria-label="Permalink to &quot;Conclusion: The leverage moved. Your job did too.&quot;">​</a></h2><p>Most developers don&#39;t need one yet - not until the task repeats, verification is automated, the budget can absorb the waste, and the agent has senior engineer tools.</p><p>Miss one condition and the loop costs more than it returns.</p><p>If you pass the test, build small. One automation. One skill. One state file. One gate. Get a manual run reliable. Turn it into a skill. Wrap it in a loop. Then schedule it. Order matters. Skip ahead and you&#39;re paying for a system no one understands.</p><p>Cherny&#39;s point isn&#39;t that the work got easier. It&#39;s that the leverage point moved. Build the loop. Stay the engineer.</p>',104)])])}const g=t(n,[["render",s]]);export{c as __pageData,g as default};
